document.addEventListener('change',e=>{if(e.target.matches('[data-pet-photo]')){const files=[...e.target.files];const status=document.getElementById('pet-photo-status');const preview=document.getElementById('pet-preview');if(!files.length){status.textContent=e.target.dataset.uploadHelp||'선명한 원본 사진을 선택해주세요.';preview.hidden=true;return}status.textContent=`${files.length}장 선택됨 · ${files.map(file=>file.name).join(', ')}`;const reader=new FileReader();reader.onload=()=>{preview.src=reader.result;preview.hidden=false};reader.readAsDataURL(files[0])}if(e.target.matches('[data-option-product]')){document.querySelectorAll('[data-variant-choice]').forEach(button=>button.classList.toggle('active',button.dataset.variantChoice===e.target.value));const variantButton=[...document.querySelectorAll('[data-variant-choice]')].find(button=>button.dataset.variantChoice===e.target.value);if(variantButton)setDetailGallery(Number(variantButton.dataset.variantGallery))}});
