const heroSlides=[...document.querySelectorAll('[data-hero-slide]')];
const hero=document.querySelector('.hero');
const heroCurrent=document.getElementById('hero-current');
const heroProgress=document.getElementById('hero-progress');
let heroActive=0,heroTimer=null;
function showHeroSlide(index,restart=false){
 if(!heroSlides.length)return;
 heroActive=(index+heroSlides.length)%heroSlides.length;
 heroSlides.forEach((slide,i)=>{const active=i===heroActive;slide.classList.toggle('active',active);slide.setAttribute('aria-hidden',String(!active))});
 heroCurrent.textContent=String(heroActive+1).padStart(2,'0');
 heroProgress.style.width=`${((heroActive+1)/heroSlides.length)*100}%`;
 if(restart)startHeroCarousel();
}
function stopHeroCarousel(){clearInterval(heroTimer);heroTimer=null}
function startHeroCarousel(){
 stopHeroCarousel();
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.hidden)return;
 heroTimer=setInterval(()=>showHeroSlide(heroActive+1),5200);
}
document.querySelector('[data-hero-prev]')?.addEventListener('click',()=>showHeroSlide(heroActive-1,true));
document.querySelector('[data-hero-next]')?.addEventListener('click',()=>showHeroSlide(heroActive+1,true));
hero?.addEventListener('mouseenter',stopHeroCarousel);
hero?.addEventListener('mouseleave',startHeroCarousel);
hero?.addEventListener('focusin',stopHeroCarousel);
hero?.addEventListener('focusout',startHeroCarousel);
document.addEventListener('visibilitychange',()=>document.hidden?stopHeroCarousel():startHeroCarousel());
window.addEventListener('moodnote-products',event=>{const live=event.detail?.products||[];if(!live.length)return;const baseMap=new Map(baseProducts.map(product=>[product.id,product]));products=live.map(item=>({...baseMap.get(item.id),description:item.description||baseMap.get(item.id)?.description||'',detail:item.detail||baseMap.get(item.id)?.detail||'',spec:item.spec||baseMap.get(item.id)?.spec||{},options:item.options?.length?item.options:baseMap.get(item.id)?.options||['기본 옵션'],...item}));render();updateCounts();const match=location.hash.match(/^#product\/(.+)$/);if(match&&byId(match[1]))renderDetail(byId(match[1]))});
showHeroSlide(0);startHeroCarousel();
